"use client";

import * as React from "react";
import { cn } from "../utils";
import { TerminalPane, type TerminalLine, createTerminalLine } from "./terminal-pane";
import { TerminalSidebar, type FileTreeNode, type TerminalSession } from "./terminal-sidebar";
import { TerminalTabBar, type TerminalTab, createTerminalTab } from "./terminal-tab-bar";
import { CommandInput } from "./command-input";
import {
  getTerminalTheme,
  type TerminalColorScheme,
  type TerminalThemeName,
} from "./terminal-theme";

export interface TerminalUIProps {
  theme?: TerminalThemeName | TerminalColorScheme;
  initialTabs?: TerminalTab[];
  initialCommands?: string[];
  files?: FileTreeNode[];
  sessions?: TerminalSession[];
  defaultCwd?: string;
  fontSize?: number;
  fontFamily?: string;
  scrollback?: number;
  showSidebar?: boolean;
  sidebarCollapsed?: boolean;
  showCommandInput?: boolean;
  multilineInput?: boolean;
  highlightSyntax?: boolean;
  autoFocus?: boolean;
  onCommand?: (command: string, tabId: string) => void;
  onTabChange?: (tabId: string) => void;
  onTabClose?: (tabId: string) => void;
  onTabAdd?: () => void;
  onFileClick?: (path: string) => void;
  onSessionClick?: (sessionId: string) => void;
  onSessionTerminate?: (sessionId: string) => void;
  onQuickAction?: (action: "new" | "split" | "settings") => void;
  className?: string;
}

const defaultFiles: FileTreeNode[] = [
  {
    name: "buildora",
    path: "/buildora",
    type: "folder",
    children: [
      {
        name: "packages",
        path: "/buildora/packages",
        type: "folder",
        children: [
          { name: "components", path: "/buildora/packages/components", type: "folder" },
          { name: "utils", path: "/buildora/packages/utils", type: "folder" },
          { name: "hooks", path: "/buildora/packages/hooks", type: "folder" },
          { name: "tokens", path: "/buildora/packages/tokens", type: "folder" },
        ],
      },
      {
        name: "apps",
        path: "/buildora/apps",
        type: "folder",
        children: [
          { name: "web", path: "/buildora/apps/web", type: "folder" },
        ],
      },
      { name: "package.json", path: "/buildora/package.json", type: "file" },
      { name: "pnpm-workspace.yaml", path: "/buildora/pnpm-workspace.yaml", type: "file" },
      { name: "tsconfig.json", path: "/buildora/tsconfig.json", type: "file" },
    ],
  },
];

export function TerminalUI({
  theme: themeProp = "dracula",
  initialTabs,
  initialCommands,
  files = defaultFiles,
  sessions = [],
  defaultCwd = "~/buildora",
  fontSize = 12,
  fontFamily = "'JetBrains Mono', 'Fira Code', 'SF Mono', Menlo, monospace",
  scrollback = 10000,
  showSidebar = true,
  sidebarCollapsed = false,
  showCommandInput = true,
  multilineInput = false,
  highlightSyntax = true,
  autoFocus = true,
  onCommand,
  onTabChange,
  onTabClose,
  onTabAdd,
  onFileClick,
  onSessionClick,
  onSessionTerminate,
  onQuickAction,
  className,
}: TerminalUIProps) {
  const theme: TerminalColorScheme = typeof themeProp === "string"
    ? getTerminalTheme(themeProp)
    : themeProp;

  const [tabs, setTabs] = React.useState<TerminalTab[]>(
    initialTabs ?? [createTerminalTab("bash", { cwd: defaultCwd, process: "bash" })]
  );
  const [activeTab, setActiveTab] = React.useState<string>(tabs[0]?.id ?? "");
  const [sidebarCollapsedState, setSidebarCollapsedState] = React.useState(sidebarCollapsed);

  const [terminalBuffers, setTerminalBuffers] = React.useState<Record<string, TerminalLine[]>>(() => {
    const initial: Record<string, TerminalLine[]> = {};
    const welcomeLines = [
      createTerminalLine(`Welcome to Buildora Terminal`, { type: "system" }),
      createTerminalLine(`Theme: ${theme.name}`, { type: "system", ansi: false }),
      createTerminalLine(``, { type: "output" }),
    ];

    if (initialCommands) {
      initialCommands.forEach((cmd) => {
        welcomeLines.push(createTerminalLine(`$ ${cmd}`, { type: "input" }));
        welcomeLines.push(createTerminalLine(`→ executed: ${cmd}`, { type: "success" }));
      });
    }

    tabs.forEach((tab) => {
      initial[tab.id] = [...welcomeLines];
    });
    return initial;
  });

  const [commandHistory, setCommandHistory] = React.useState<string[]>([]);

  const handleCommandSubmit = React.useCallback((command: string) => {
    if (!command.trim()) return;

    const newLine = createTerminalLine(`$ ${command}`, { type: "input" });
    const outputLine = createTerminalLine(`→ Running: ${command}`, { type: "output" });

    setCommandHistory((prev) => [...prev, command]);
    setTerminalBuffers((prev) => ({
      ...prev,
      [activeTab]: [...(prev[activeTab] ?? []), newLine, outputLine],
    }));

    onCommand?.(command, activeTab);
  }, [activeTab, onCommand]);

  const handleTabChange = React.useCallback((tabId: string) => {
    setActiveTab(tabId);
    onTabChange?.(tabId);
  }, [onTabChange]);

  const handleTabClose = React.useCallback((tabId: string) => {
    setTabs((prev) => {
      const newTabs = prev.filter((t) => t.id !== tabId);
      if (newTabs.length === 0) {
        newTabs.push(createTerminalTab("bash", { cwd: defaultCwd }));
        setTerminalBuffers((prevBuffs) => {
          const newBuffer: Record<string, TerminalLine[]> = {};
          newTabs.forEach((t) => {
            newBuffer[t.id] = prevBuffs[t.id] ?? [];
          });
          return newBuffer;
        });
      }
      if (activeTab === tabId) {
        setActiveTab(newTabs[0]?.id ?? "");
      }
      return newTabs;
    });
    onTabClose?.(tabId);
  }, [activeTab, defaultCwd, onTabClose]);

  const handleTabAdd = React.useCallback(() => {
    const newTab = createTerminalTab(`term-${tabs.length + 1}`, { cwd: defaultCwd });
    setTabs((prev) => [...prev, newTab]);
    setTerminalBuffers((prev) => ({
      ...prev,
      [newTab.id]: [createTerminalLine(`New terminal session`, { type: "system" })],
    }));
    setActiveTab(newTab.id);
    onTabAdd?.();
  }, [tabs.length, defaultCwd, onTabAdd]);

  const handleQuickAction = React.useCallback((action: "new" | "split" | "settings") => {
    if (action === "new") {
      handleTabAdd();
    }
    onQuickAction?.(action);
  }, [handleTabAdd, onQuickAction]);

  const activeLines = terminalBuffers[activeTab] ?? [];

  return (
    <div
      className={cn(
        "flex h-full w-full overflow-hidden",
        className
      )}
      style={{ backgroundColor: theme.background }}
    >
      {showSidebar && (
        <TerminalSidebar
          theme={theme}
          collapsed={sidebarCollapsedState}
          onCollapseChange={setSidebarCollapsedState}
          files={files}
          sessions={sessions}
          processes={sessions.map((s) => ({ ...s, pid: Math.floor(Math.random() * 10000) }))}
          activeSession={activeTab}
          onFileClick={onFileClick ?? (() => {})}
          onSessionClick={onSessionClick}
          onSessionTerminate={onSessionTerminate}
          onQuickAction={handleQuickAction}
        />
      )}

      <div className="flex flex-col flex-1 overflow-hidden">
        <TerminalTabBar
          tabs={tabs}
          activeTab={activeTab}
          onTabChange={handleTabChange}
          onTabClose={handleTabClose}
          onTabAdd={handleTabAdd}
          theme={theme}
        />

        <TerminalPane
          lines={activeLines}
          theme={theme}
          scrollback={scrollback}
          fontSize={fontSize}
          fontFamily={fontFamily}
          className="flex-1"
        />

        {showCommandInput && (
          <div className="border-t" style={{ borderColor: theme.brightBlack, padding: "8px" }}>
            <CommandInput
              theme={theme}
              history={commandHistory}
              onSubmit={handleCommandSubmit}
              multiline={multilineInput}
              showLineNumbers={multilineInput}
              highlight={highlightSyntax}
              autoFocus={autoFocus}
              suggestions={[
                { text: "npm install", description: "Install dependencies" },
                { text: "npm run dev", description: "Start dev server" },
                { text: "npm run build", description: "Build project" },
                { text: "npm run test", description: "Run tests" },
                { text: "git status", description: "Check git status" },
                { text: "git diff", description: "Show changes" },
                { text: "pnpm install", description: "Install with pnpm" },
                { text: "pnpm dev", description: "Start dev server" },
                { text: "clear", description: "Clear terminal" },
                { text: "ls -la", description: "List files" },
              ]}
            />
          </div>
        )}
      </div>
    </div>
  );
}

export {
  TerminalPane,
  TerminalSidebar,
  TerminalTabBar,
  CommandInput,
  createTerminalLine,
  createTerminalTab,
  getTerminalTheme,
};

export {
  terminalThemes,
  createCustomTheme,
  ansiColorToCSS,
} from "./terminal-theme";

export type {
  TerminalLine,
  TerminalPaneProps,
} from "./terminal-pane";

export type {
  TerminalTab,
  TerminalTabBarProps,
} from "./terminal-tab-bar";

export type {
  FileTreeNode,
  TerminalSession,
  TerminalSidebarProps,
} from "./terminal-sidebar";

export type {
  CommandSuggestion,
  CommandInputProps,
} from "./command-input";

export type {
  TerminalColorScheme,
  TerminalThemeName,
} from "./terminal-theme";

"use client";

import * as React from "react";
import { cn } from "../utils";
import { type TerminalColorScheme, ansiColorToCSS } from "./terminal-theme";

export interface TerminalLine {
  id: string;
  content: string;
  timestamp?: number;
  type?: "input" | "output" | "error" | "warning" | "success" | "system";
  ansi?: boolean;
}

export interface TerminalPaneProps {
  lines: TerminalLine[];
  theme: TerminalColorScheme;
  scrollback?: number;
  fontSize?: number;
  fontFamily?: string;
  lineHeight?: number;
  cursor?: boolean;
  cursorBlink?: boolean;
  className?: string;
  onSelect?: (text: string, range: { start: number; end: number }) => void;
  onScroll?: (position: number) => void;
}

const ansiRegex = /\x1b\[([0-9;]*)m/g;

function parseAnsi(text: string): Array<{ text: string; styles: React.CSSProperties }> {
  const parts: Array<{ text: string; styles: React.CSSProperties }> = [];
  let currentStyles: React.CSSProperties = {};
  let remaining = text;

  while (remaining.length > 0) {
    const match = remaining.match(ansiRegex);
    if (!match || match.index === undefined) {
      if (remaining.length > 0) {
        parts.push({ text: remaining, styles: currentStyles });
      }
      break;
    }

    if (match.index > 0) {
      parts.push({ text: remaining.slice(0, match.index), styles: currentStyles });
    }

    const codes = match[1].split(";").map(Number);
    codes.forEach((code) => {
      currentStyles = applyAnsiCode(currentStyles, code);
    });

    remaining = remaining.slice(match.index! + match[0].length);
  }

  return parts;
}

function applyAnsiCode(styles: React.CSSProperties, code: number): React.CSSProperties {
  const newStyles = { ...styles };

  if (code === 0) {
    return {};
  } else if (code === 1) {
    newStyles.fontWeight = "bold";
  } else if (code === 3) {
    newStyles.fontStyle = "italic";
  } else if (code === 4) {
    newStyles.textDecoration = "underline";
  } else if (code === 7) {
    const bg = newStyles.backgroundColor as string | undefined;
    const fg = newStyles.color as string | undefined;
    if (bg) newStyles.color = bg;
    if (fg) newStyles.backgroundColor = fg;
  } else if (code === 22) {
    newStyles.fontWeight = "normal";
  } else if (code === 23) {
    newStyles.fontStyle = "normal";
  } else if (code === 24) {
    newStyles.textDecoration = "none";
  } else if (code === 30) {
    newStyles.color = ansiColorToCSS("30");
  } else if (code === 31) {
    newStyles.color = ansiColorToCSS("31");
  } else if (code === 32) {
    newStyles.color = ansiColorToCSS("32");
  } else if (code === 33) {
    newStyles.color = ansiColorToCSS("33");
  } else if (code === 34) {
    newStyles.color = ansiColorToCSS("34");
  } else if (code === 35) {
    newStyles.color = ansiColorToCSS("35");
  } else if (code === 36) {
    newStyles.color = ansiColorToCSS("36");
  } else if (code === 37) {
    newStyles.color = ansiColorToCSS("37");
  } else if (code === 90) {
    newStyles.color = ansiColorToCSS("90");
  } else if (code === 91) {
    newStyles.color = ansiColorToCSS("91");
  } else if (code === 92) {
    newStyles.color = ansiColorToCSS("92");
  } else if (code === 93) {
    newStyles.color = ansiColorToCSS("93");
  } else if (code === 94) {
    newStyles.color = ansiColorToCSS("94");
  } else if (code === 95) {
    newStyles.color = ansiColorToCSS("95");
  } else if (code === 96) {
    newStyles.color = ansiColorToCSS("96");
  } else if (code === 97) {
    newStyles.color = ansiColorToCSS("97");
  }

  return newStyles;
}

function renderLineContent(line: TerminalLine, theme: TerminalColorScheme) {
  if (!line.ansi) {
    let color = theme.foreground;
    if (line.type === "input") color = theme.cyan;
    else if (line.type === "error") color = theme.red;
    else if (line.type === "warning") color = theme.yellow;
    else if (line.type === "success") color = theme.green;
    else if (line.type === "system") color = theme.magenta;

    return <span style={{ color }}>{line.content}</span>;
  }

  const parts = parseAnsi(line.content);
  return parts.map((part, idx) => (
    <span key={idx} style={part.styles}>{part.text}</span>
  ));
}

export function TerminalPane({
  lines,
  theme,
  scrollback = 10000,
  fontSize = 12,
  fontFamily = "'JetBrains Mono', 'Fira Code', 'SF Mono', Menlo, monospace",
  lineHeight = 1.4,
  cursor = true,
  cursorBlink = true,
  className,
  onSelect,
  onScroll,
}: TerminalPaneProps) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [selection, setSelection] = React.useState<{ start: number; end: number } | null>(null);
  const [isSelecting, setIsSelecting] = React.useState(false);
  const [autoScroll, setAutoScroll] = React.useState(true);

  const displayLines = React.useMemo(() => {
    return lines.slice(-scrollback);
  }, [lines, scrollback]);

  React.useEffect(() => {
    if (autoScroll && containerRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [displayLines.length, autoScroll]);

  const handleScroll = React.useCallback((e: React.UIEvent<HTMLDivElement>) => {
    const target = e.currentTarget;
    const isAtBottom = target.scrollHeight - target.scrollTop <= target.clientHeight + 5;
    setAutoScroll(isAtBottom);
    onScroll?.(target.scrollTop);
  }, [onScroll]);

  const handleMouseDown = React.useCallback((e: React.MouseEvent) => {
    if (e.shiftKey) return;
    setIsSelecting(true);
    setSelection(null);
  }, []);

  const handleMouseUp = React.useCallback(() => {
    setIsSelecting(false);
    const selectedText = window.getSelection()?.toString() ?? "";
    if (selectedText && selection && onSelect) {
      onSelect(selectedText, selection);
    }
  }, [selection, onSelect]);

  const handleMouseMove = React.useCallback(() => {
    if (!isSelecting) return;
    const sel = window.getSelection();
    if (sel && sel.rangeCount > 0) {
      const range = sel.getRangeAt(0);
      setSelection({
        start: range.startOffset,
        end: range.endOffset,
      });
    }
  }, [isSelecting]);

  return (
    <div
      ref={containerRef}
      className={cn(
        "flex-1 overflow-auto outline-none select-text",
        className
      )}
      style={{
        fontSize,
        fontFamily,
        lineHeight,
        backgroundColor: theme.background,
        color: theme.foreground,
        cursor: "text",
      }}
      tabIndex={0}
      role="textbox"
      aria-label="Terminal output"
      aria-multiline="true"
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onMouseMove={handleMouseMove}
      onScroll={handleScroll}
    >
      <div className="min-h-full" style={{ padding: "4px 8px" }}>
        {displayLines.map((line, idx) => (
          <div
            key={line.id ?? `${idx}-${line.timestamp}`}
            className="whitespace-pre-wrap break-all"
          >
            {renderLineContent(line, theme)}
          </div>
        ))}
        {cursor && (
          <span
            className={cn(
              "inline-block w-2 h-[1.1em] align-middle",
              cursorBlink && "animate-[terminal-blink_1s_step-end_infinite]"
            )}
            style={{ backgroundColor: theme.cursor }}
            aria-hidden
          />
        )}
      </div>
      <style>{`
        @keyframes terminal-blink {
          0%, 100% { opacity: 1; }
          50% { opacity: 0; }
        }
      `}</style>
    </div>
  );
}

export function createTerminalLine(
  content: string,
  options?: Partial<TerminalLine>
): TerminalLine {
  return {
    id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    content,
    timestamp: Date.now(),
    type: "output",
    ansi: false,
    ...options,
  };
}

"use client";

import * as React from "react";
import { cn } from "../utils";
import { type TerminalColorScheme } from "./terminal-theme";

export interface FileTreeNode {
  name: string;
  path: string;
  type: "file" | "folder";
  children?: FileTreeNode[];
  icon?: React.ReactNode;
}

export interface TerminalSession {
  id: string;
  name: string;
  cwd?: string;
  processName?: string;
  pid?: number;
  status?: "active" | "stopped" | "exited";
  connections?: number;
}

export interface TerminalSidebarProps {
  theme: TerminalColorScheme;
  collapsed?: boolean;
  onCollapseChange?: (collapsed: boolean) => void;
  files?: FileTreeNode[];
  sessions?: TerminalSession[];
  processes?: TerminalSession[];
  activeSession?: string | null;
  onFileClick?: (path: string) => void;
  onSessionClick?: (sessionId: string) => void;
  onProcessClick?: (pid: number) => void;
  onSessionTerminate?: (sessionId: string) => void;
  onQuickAction?: (action: "new" | "split" | "settings") => void;
  className?: string;
}

const folderIcon = (
  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" />
  </svg>
);

const fileIcon = (
  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
  </svg>
);

function FileTreeItem({
  node,
  theme,
  depth,
  onFileClick,
}: {
  node: FileTreeNode;
  theme: TerminalColorScheme;
  depth: number;
  onFileClick: (path: string) => void;
}) {
  const [expanded, setExpanded] = React.useState(depth < 1);
  const hasChildren = node.children && node.children.length > 0;

  return (
    <li role="treeitem" aria-expanded={hasChildren ? expanded : undefined}>
      <div
        className={cn(
          "flex items-center gap-1 px-1 py-0.5 rounded cursor-pointer",
          "hover:bg-white/5 transition-colors"
        )}
        style={{
          paddingLeft: `${8 + depth * 12}px`,
          color: theme.foreground,
        }}
        onClick={() => {
          if (hasChildren) {
            setExpanded(!expanded);
          } else {
            onFileClick(node.path);
          }
        }}
      >
        <span className="shrink-0" style={{ color: theme.brightBlack }}>
          {hasChildren ? (expanded ? "▾" : "▸") : " "}
        </span>
        <span className="shrink-0" style={{ color: node.type === "folder" ? theme.yellow : theme.cyan }}>
          {node.icon ?? (node.type === "folder" ? folderIcon : fileIcon)}
        </span>
        <span className="truncate text-xs font-mono">{node.name}</span>
      </div>
      {hasChildren && expanded && (
        <ul role="group" className="m-0 p-0 list-none">
          {node.children!.map((child) => (
            <FileTreeItem
              key={child.path}
              node={child}
              theme={theme}
              depth={depth + 1}
              onFileClick={onFileClick}
            />
          ))}
        </ul>
      )}
    </li>
  );
}

const statusColors: Record<string, string> = {
  active: "bg-green-500",
  stopped: "bg-yellow-500",
  exited: "bg-red-500",
};

export function TerminalSidebar({
  theme,
  collapsed = false,
  onCollapseChange,
  files,
  sessions = [],
  processes = [],
  activeSession,
  onFileClick = () => {},
  onSessionClick,
  onProcessClick,
  onSessionTerminate,
  onQuickAction,
  className,
}: TerminalSidebarProps) {
  const [activeSection, setActiveSection] = React.useState<"files" | "sessions" | "processes">("files");

  if (collapsed) {
    return (
      <aside
        className={cn(
          "flex flex-col w-12 border-r items-center py-2 gap-2",
          className
        )}
        style={{
          backgroundColor: theme.background,
          borderColor: theme.brightBlack,
        }}
      >
        <button
          type="button"
          className="p-2 rounded hover:bg-white/5"
          style={{ color: theme.foreground }}
          onClick={() => onCollapseChange?.(false)}
          aria-label="Expand sidebar"
        >
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" />
          </svg>
        </button>
      </aside>
    );
  }

  return (
    <aside
      className={cn(
        "flex flex-col w-56 h-full border-r overflow-hidden",
        className
      )}
      style={{
        backgroundColor: theme.background,
        borderColor: theme.brightBlack,
      }}
    >
      <div
        className="flex items-center justify-between px-3 py-2 border-b"
        style={{ borderColor: theme.brightBlack }}
      >
        <span
          className="text-xs font-semibold uppercase tracking-wider"
          style={{ color: theme.brightBlack }}
        >
          Explorer
        </span>
        <button
          type="button"
          className="p-1 rounded hover:bg-white/5"
          style={{ color: theme.brightBlack }}
          onClick={() => onCollapseChange?.(true)}
          aria-label="Collapse sidebar"
        >
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 19l-7-7 7-7m8 14l-7-7 7-7" />
          </svg>
        </button>
      </div>

      <div className="flex border-b" style={{ borderColor: theme.brightBlack }}>
        {["files", "sessions", "processes"].map((section) => (
          <button
            key={section}
            type="button"
            className={cn(
              "flex-1 px-3 py-2 text-xs font-mono capitalize transition-colors",
              activeSection === section && "border-b-2"
            )}
            style={{
              color: activeSection === section ? theme.foreground : theme.brightBlack,
              borderColor: activeSection === section ? theme.cyan : "transparent",
            }}
            onClick={() => setActiveSection(section as typeof activeSection)}
            aria-selected={activeSection === section}
            role="tab"
          >
            {section}
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-auto py-2">
        {activeSection === "files" && files && (
          <ul role="tree" className="m-0 p-0 list-none">
            {files.map((node) => (
              <FileTreeItem
                key={node.path}
                node={node}
